const body = ($json.body) || {};
const headers = ($json.headers) || {};
let texts = [];
if (Array.isArray(body.texts)) texts = body.texts;
else if (body.text != null) texts = [body.text];
if (texts.length === 0) texts = [''];
const requester = body.requester || headers['x-requester'] || 'anonymous';
const context = body.context || '';
return texts.map(function (t, i) { return { json: { id: i + 1, text: String(t == null ? '' : t), context: context, requester: requester } }; });

