const meta = $('Normalize Request').item.json;
const d = $json.output || {};
const join = function (x) { return Array.isArray(x) ? x.join(', ') : (x || ''); };
const has = (typeof d.action === 'string');
return {
  id: meta.id,
  requester: meta.requester,
  text: meta.text,
  action: has ? String(d.action).toLowerCase() : 'flag',
  toxicity: d.toxicity || 'unknown',
  categories: join(d.categories),
  containsPii: d.contains_pii ? true : false,
  piiFound: join(d.pii_found),
  reason: has ? (d.reason || '') : 'Moderation engine did not return a result; defaulted to human review.',
  cleanedText: d.cleaned_text || meta.text
};

const rows = $json.data || [];
const results = rows.map(function (r) { return { id: r.id, action: r.action, toxicity: r.toxicity, categories: r.categories, contains_pii: r.containsPii, pii_found: r.piiFound, reason: r.reason, cleaned_text: r.cleanedText }; });
const count = function (a) { return results.filter(function (r) { return r.action === a; }).length; };
const blocked = count('block');
const flagged = count('flag');
return { summary: { total: results.length, blocked: blocked, flagged: flagged, allowed: results.length - blocked - flagged }, results: results };
